return-response.set-body:
@{
				var prefix = "/.well-known/oauth-protected-resource";
				var path = context.Request.OriginalUrl.Path;
				var resource = "https://" + context.Request.OriginalUrl.Host + path.Substring(prefix.Length);
				return new JObject(
					new JProperty("resource", resource),
					new JProperty("authorization_servers", new JArray("https://[[login_host]]/{{[[tenant_named_value]]}}/v2.0")),
					new JProperty("bearer_methods_supported", new JArray("header"))
				).ToString();
			}
